def _validate_frequency(frequency: int, samplerate: int, q_factor: float) -> None:
    """Validate arguments shared by the Butterworth filter factories."""
    if not isinstance(frequency, int) or frequency <= 0:
        raise ValueError("frequency must be a positive integer")
    if not isinstance(samplerate, int) or samplerate <= 0:
        raise ValueError("samplerate must be a positive integer")
    if frequency >= samplerate / 2:
        raise ValueError("frequency must be less than half the samplerate")
    if q_factor <= 0:
        raise ValueError("q_factor must be positive")

def and_gate(input_1: int, input_2: int) -> int:
    """Calculate AND of two binary input values."""
    # Type validation
    if not isinstance(input_1, int) or not isinstance(input_2, int):
        raise TypeError("Both inputs must be integers")

    # Value validation
    if input_1 not in (0, 1) or input_2 not in (0, 1):
        raise ValueError("Both inputs must be 0 or 1")

    return input_1 & input_2

def new_generation(cells: list[list[int]]) -> list[list[int]]:
    """Generates the next generation for a given state of Conway's Game of Life."""
    next_generation = []
    for i in range(len(cells)):
        next_generation_row = []
        for j in range(len(cells[i])):
            # Get the number of live neighbours
            neighbour_count = 0
            if i > 0 and j > 0:
                neighbour_count += cells[i - 1][j - 1]
            if i > 0:
                neighbour_count += cells[i - 1][j]
            if i > 0 and j < len(cells[i]) - 1:
                neighbour_count += cells[i - 1][j + 1]
            if j > 0:
                neighbour_count += cells[i][j - 1]
            if j < len(cells[i]) - 1:
                neighbour_count += cells[i][j + 1]
            if i < len(cells) - 1 and j > 0:
                neighbour_count += cells[i + 1][j - 1]
            if i < len(cells) - 1:
                neighbour_count += cells[i + 1][j]
            if i < len(cells) - 1 and j < len(cells[i]) - 1:
                neighbour_count += cells[i + 1][j + 1]

            # Rules of the game of life (excerpt from Wikipedia):
            # 1. Any live cell with two or three live neighbours survives.
            # 2. Any dead cell with three live neighbours becomes a live cell.
            # 3. All other live cells die in the next generation.
            #    Similarly, all other dead cells stay dead.
            alive = cells[i][j] == 1
            if (alive and 2 <= neighbour_count <= 3) or (
                not alive and neighbour_count == 3
            ):
                next_generation_row.append(1)
            else:
                next_generation_row.append(0)

        next_generation.append(next_generation_row)
    return next_generation

def check_keys(key_a: int, key_b: int, mode: str) -> None:
    if mode == "encrypt":
        if key_a == 1:
            sys.exit(
                "The affine cipher becomes weak when key "
                "A is set to 1. Choose different key"
            )
        if key_b == 0:
            sys.exit(
                "The affine cipher becomes weak when key "
                "B is set to 0. Choose different key"
            )
    if key_a < 0 or key_b < 0 or key_b > len(SYMBOLS) - 1:
        sys.exit(
            "Key A must be greater than 0 and key B must "
            f"be between 0 and {len(SYMBOLS) - 1}."
        )
    if gcd_by_iterative(key_a, len(SYMBOLS)) != 1:
        sys.exit(
            f"Key A {key_a} and the symbol set size {len(SYMBOLS)} "
            "are not relatively prime. Choose a different key."
        )

def length_conversion(value: float, from_type: str, to_type: str) -> float:
    """Conversion between astronomical length units."""

    from_sanitized = from_type.lower().strip("s")
    to_sanitized = to_type.lower().strip("s")

    from_sanitized = UNIT_SYMBOL.get(from_sanitized, from_sanitized)
    to_sanitized = UNIT_SYMBOL.get(to_sanitized, to_sanitized)

    if from_sanitized not in METRIC_CONVERSION:
        msg = (
            f"Invalid 'from_type' value: {from_type!r}.\n"
            f"Conversion abbreviations are: {', '.join(METRIC_CONVERSION)}"
        )
        raise ValueError(msg)
    if to_sanitized not in METRIC_CONVERSION:
        msg = (
            f"Invalid 'to_type' value: {to_type!r}.\n"
            f"Conversion abbreviations are: {', '.join(METRIC_CONVERSION)}"
        )
        raise ValueError(msg)
    from_exponent = METRIC_CONVERSION[from_sanitized]
    to_exponent = METRIC_CONVERSION[to_sanitized]
    exponent = 1

    if from_exponent > to_exponent:
        exponent = from_exponent - to_exponent
    else:
        exponent = -(to_exponent - from_exponent)

    return value * pow(10, exponent)

def bwt_transform(s: str) -> BWTTransformDict:
    """:param s: The string that will be used at bwt algorithm"""
    if not isinstance(s, str):
        raise TypeError("The parameter s type must be str.")
    if not s:
        raise ValueError("The parameter s must not be empty.")

    rotations = all_rotations(s)
    rotations.sort()  # sort the list of rotations in alphabetically order
    # make a string composed of the last char of each rotation
    response: BWTTransformDict = {
        "bwt_string": "".join([word[-1] for word in rotations]),
        "idx_original_string": rotations.index(s),
    }
    return response

def equilibrium_index(arr: list[int]) -> int:
    """Find the first equilibrium index of an array."""
    total_sum = sum(arr)
    left_sum = 0
    for i, value in enumerate(arr):
        total_sum -= value
        if left_sum == total_sum:
            return i
        left_sum += value
    return -1

def convert_to_negative(img):
    # getting number of pixels in the image
    pixel_h, pixel_v = img.shape[0], img.shape[1]

    # converting each pixel's color to its negative
    for i in range(pixel_h):
        for j in range(pixel_v):
            img[i][j] = [255, 255, 255] - img[i][j]

    return img

def dis_between_closest_pair(points, points_counts, min_dis=float("inf")):
    """brute force approach to find distance between closest pair points"""

    for i in range(points_counts - 1):
        for j in range(i + 1, points_counts):
            current_dis = euclidean_distance_sqr(points[i], points[j])
            min_dis = min(min_dis, current_dis)
    return min_dis

def abbr(a: str, b: str) -> bool:
    n = len(a)
    m = len(b)
    dp = [[False for _ in range(m + 1)] for _ in range(n + 1)]
    dp[0][0] = True
    for i in range(n):
        for j in range(m + 1):
            if dp[i][j]:
                if j < m and a[i].upper() == b[j]:
                    dp[i + 1][j + 1] = True
                if a[i].islower():
                    dp[i + 1][j] = True
    return dp[n][m]

def annuity_due_future_value(
    term_payment: float, number_of_payments: int, term_interest_rate: float
) -> float:
    """Calculate the future value of the given annuity due"""

    annuity_factor = (
        ((1 + term_interest_rate) ** number_of_payments) - 1
    ) / term_interest_rate
    future_value = term_payment * annuity_factor * (1 + term_interest_rate)
    return future_value

def transform(point: tuple[float, float], index: int) -> tuple[float, float]:
    """Apply the affine transformation ``index`` to ``point`` and return the image."""
    if not 0 <= index < len(TRANSFORMATIONS):
        msg = f"index must be in range 0..3, got {index}"
        raise IndexError(msg)
    a, b, c, d, e, f = TRANSFORMATIONS[index]
    x, y = point
    new_x = round(a * x + b * y + e, 12)
    new_y = round(c * x + d * y + f, 12)
    return (new_x, new_y)

def triangular_membership(
    grid: NDArray[np.float64], left: float, peak: float, right: float
) -> NDArray[np.float64]:
    """Sample a triangular membership function on the ``grid``."""
    if not left <= peak <= right:
        msg = f"Expected left <= peak <= right, got {left}, {peak}, {right}"
        raise ValueError(msg)
    left_slope = (
        (grid - left) / (peak - left) if peak > left else np.where(grid < peak, 0, 1)
    )
    right_slope = (
        (right - grid) / (right - peak) if right > peak else np.where(grid > peak, 0, 1)
    )
    return np.clip(np.minimum(left_slope, right_slope), 0.0, 1.0)

