def knapsack(
    capacity: int,
    weights: list[int],
    values: list[int],
    counter: int,
    allow_repetition=False,
) -> int:
    """Returns the maximum value that can be put in a knapsack of a capacity cap,"""

    @lru_cache
    def knapsack_recur(capacity: int, counter: int) -> int:
        # Base Case
        if counter == 0 or capacity == 0:
            return 0

        # If weight of the nth item is more than Knapsack of capacity,
        #   then this item cannot be included in the optimal solution,
        # else return the maximum of two cases:
        #   (1) nth item included only once (0-1), if allow_repetition is False
        #       nth item included one or more times (0-N), if allow_repetition is True
        #   (2) not included
        if weights[counter - 1] > capacity:
            return knapsack_recur(capacity, counter - 1)
        else:
            left_capacity = capacity - weights[counter - 1]
            new_value_included = values[counter - 1] + knapsack_recur(
                left_capacity, counter - 1 if not allow_repetition else counter
            )
            without_new_value = knapsack_recur(capacity, counter - 1)
            return max(new_value_included, without_new_value)

    return knapsack_recur(capacity, counter)

def gauss_jordan(
    coefficients: np.ndarray, vertices: np.ndarray
) -> tuple[np.ndarray, np.ndarray]:
    """Performs Gauss-Jordan elimination on the system Ax = b to reduce A to its"""
    if coefficients.ndim != 2 or vertices.ndim != 2:
        raise ValueError("Both inputs must be 2D arrays.")
    if coefficients.shape[0] != vertices.shape[0]:
        raise ValueError("Number of rows in coefficients and vertices must match.")

    coefficients = coefficients.astype(float).copy()
    vertices = vertices.astype(float).copy()
    rows, cols = coefficients.shape

    for col in range(cols):
        pivot_row = None
        for row in range(col, rows):
            if not np.isclose(coefficients[row, col], 0):
                pivot_row = row
                break

        if pivot_row is None:
            continue

        if pivot_row != col:
            coefficients[[col, pivot_row]] = coefficients[[pivot_row, col]]
            vertices[[col, pivot_row]] = vertices[[pivot_row, col]]

        pivot_val = coefficients[col, col]
        coefficients[col] /= pivot_val
        vertices[col] /= pivot_val

        for row in range(rows):
            if row == col:
                continue
            factor = coefficients[row, col]
            coefficients[row] -= factor * coefficients[col]
            vertices[row] -= factor * vertices[col]

    return coefficients, vertices

def prune(itemset: list, candidates: list, length: int) -> list:
    """Prune candidate itemsets that are not frequent."""
    itemset_counter = Counter(tuple(item) for item in itemset)
    pruned = []
    for candidate in candidates:
        is_subsequence = True
        for item in candidate:
            item_tuple = tuple(item)
            if (
                item_tuple not in itemset_counter
                or itemset_counter[item_tuple] < length - 1
            ):
                is_subsequence = False
                break
        if is_subsequence:
            pruned.append(candidate)
    return pruned

