def bisect_left(
    sorted_collection: list[int], item: int, lo: int = 0, hi: int = -1
) -> int:
    """Locates the first element in a sorted array that is larger or equal to a given"""
    if hi < 0:
        hi = len(sorted_collection)

    while lo < hi:
        mid = lo + (hi - lo) // 2
        if sorted_collection[mid] < item:
            lo = mid + 1
        else:
            hi = mid

    return lo

def adaptive_merge_sort_helper[T: Comparable](
    array: list[T], aux: list[T], low: int, high: int
) -> None:
    if high <= low:
        return

    mid = (low + high) // 2

    adaptive_merge_sort_helper(aux, array, low, mid)
    adaptive_merge_sort_helper(aux, array, mid + 1, high)

    if not array[mid + 1] < array[mid]:
        array[low : high + 1] = aux[low : high + 1]
        return

    merge(array, aux, low, mid, high)

def alternative_string_arrange(first_str: str, second_str: str) -> str:
    """Return the alternative arrangements of the two strings."""
    first_str_length: int = len(first_str)
    second_str_length: int = len(second_str)
    abs_length: int = (
        first_str_length if first_str_length > second_str_length else second_str_length
    )
    output_list: list = []
    for char_count in range(abs_length):
        if char_count < first_str_length:
            output_list.append(first_str[char_count])
        if char_count < second_str_length:
            output_list.append(second_str[char_count])
    return "".join(output_list)

def n_input_and_gate(inputs: list[int]) -> int:
    """Calculate AND of a list of binary input values."""
    # Type validation for the list itself
    if not isinstance(inputs, list):
        raise TypeError("Input must be a list")

    # Edge case validation for an empty list
    if not inputs:
        raise ValueError("Input list cannot be empty")

    # Type and value validation for items within the list
    for item in inputs:
        if not isinstance(item, int):
            raise TypeError("All inputs in the list must be integers")
        if item not in (0, 1):
            raise ValueError("All inputs in the list must be 0 or 1")

    return int(all(inputs))

def encrypt_message(key: int, message: str) -> str:
    key_a, key_b = divmod(key, len(SYMBOLS))
    check_keys(key_a, key_b, "encrypt")
    cipher_text = ""
    for symbol in message:
        if symbol in SYMBOLS:
            sym_index = SYMBOLS.find(symbol)
            cipher_text += SYMBOLS[(sym_index * key_a + key_b) % len(SYMBOLS)]
        else:
            cipher_text += symbol
    return cipher_text

def base64_to_bin(base64_str: str) -> str:
    """Convert a base64 value to its binary equivalent."""
    b64_str = str(base64_str).strip()
    if not b64_str:
        raise ValueError("Empty string was passed to the function")
    is_negative = b64_str[0] == "-"
    if is_negative:
        b64_str = b64_str[1:]
    bin_str = ""
    for i, x in enumerate(b64_str):
        if x not in B64_TO_BITS:
            exception_message = f"Invalid base64 string. Invalid char {x} at pos {i}"
            raise ValueError(exception_message)
        bin_str += B64_TO_BITS[x]
    if is_negative:
        bin_str = "-" + bin_str
    return bin_str

def reverse_bwt(bwt_string: str, idx_original_string: int) -> str:
    """:param bwt_string: The string returned from bwt algorithm execution"""
    if not isinstance(bwt_string, str):
        raise TypeError("The parameter bwt_string type must be str.")
    if not bwt_string:
        raise ValueError("The parameter bwt_string must not be empty.")
    try:
        idx_original_string = int(idx_original_string)
    except ValueError:
        raise TypeError(
            "The parameter idx_original_string type must be int or passive"
            " of cast to int."
        )
    if idx_original_string < 0:
        raise ValueError("The parameter idx_original_string must not be lower than 0.")
    if idx_original_string >= len(bwt_string):
        raise ValueError(
            "The parameter idx_original_string must be lower than len(bwt_string)."
        )

    ordered_rotations = [""] * len(bwt_string)
    for _ in range(len(bwt_string)):
        for i in range(len(bwt_string)):
            ordered_rotations[i] = bwt_string[i] + ordered_rotations[i]
        ordered_rotations.sort()
    return ordered_rotations[idx_original_string]

def dis_between_closest_in_strip(points, points_counts, min_dis=float("inf")):
    """closest pair of points in strip"""

    for i in range(min(6, points_counts - 1), points_counts):
        for j in range(max(0, i - 6), i):
            current_dis = euclidean_distance_sqr(points[i], points[j])
            min_dis = min(min_dis, current_dis)
    return min_dis

def builtin_voltage(
    donor_conc: float,  # donor concentration
    acceptor_conc: float,  # acceptor concentration
    intrinsic_conc: float,  # intrinsic concentration
) -> float:
    """This function can calculate the Builtin Voltage of a pn junction diode."""

    if donor_conc <= 0:
        raise ValueError("Donor concentration should be positive")
    if acceptor_conc <= 0:
        raise ValueError("Acceptor concentration should be positive")
    if intrinsic_conc <= 0:
        raise ValueError("Intrinsic concentration should be positive")
    if donor_conc <= intrinsic_conc:
        raise ValueError(
            "Donor concentration should be greater than intrinsic concentration"
        )
    if acceptor_conc <= intrinsic_conc:
        raise ValueError(
            "Acceptor concentration should be greater than intrinsic concentration"
        )
    return (
        Boltzmann
        * T
        * log((donor_conc * acceptor_conc) / intrinsic_conc**2)
        / physical_constants["electron volt"][0]
    )

def equated_monthly_installments(
    principal: float, rate_per_annum: float, years_to_repay: int
) -> float:
    """Formula for amortization amount per month:"""
    if principal <= 0:
        raise Exception("Principal borrowed must be > 0")
    if rate_per_annum < 0:
        raise Exception("Rate of interest must be >= 0")
    if years_to_repay <= 0 or not isinstance(years_to_repay, int):
        raise Exception("Years to repay must be an integer > 0")

    # Yearly rate is divided by 12 to get monthly rate
    rate_per_month = rate_per_annum / 12

    # Years to repay is multiplied by 12 to get number of payments as payment is monthly
    number_of_payments = years_to_repay * 12

    return (
        principal
        * rate_per_month
        * (1 + rate_per_month) ** number_of_payments
        / ((1 + rate_per_month) ** number_of_payments - 1)
    )

