def _linear_interpolated_quantile(
    sorted_values: Sequence[float], quantile: float
) -> float:
    """Linear interpolation between the closest ranks (NumPy default, type 7)."""
    position = (len(sorted_values) - 1) * quantile
    lower_index = int(position)
    fraction = position - lower_index
    if lower_index == len(sorted_values) - 1:
        return sorted_values[-1]
    return sorted_values[lower_index] * (1 - fraction) + (
        sorted_values[lower_index + 1] * fraction
    )

def hilbert_curve(
    center: tuple[float, float], level: int, side: float = 1, angle: int = 90
) -> list[tuple[float, float]]:
    """Params:"""
    x, y = center
    angle = angle % 360
    pnts = [
        (x + side / 4, y + side / 4),
        (x - side / 4, y + side / 4),
        (x - side / 4, y - side / 4),
        (x + side / 4, y - side / 4),
    ]
    pnts = rotate_pnts(pnts, angle)

    if level == 1:
        return pnts
    else:
        return (
            hilbert_curve(pnts[0], level - 1, side / 2, angle=angle + 90)[::-1]
            + hilbert_curve(pnts[1], level - 1, side / 2, angle=angle)
            + hilbert_curve(pnts[2], level - 1, side / 2, angle=angle)
            + hilbert_curve(pnts[3], level - 1, side / 2, angle=angle - 90)[::-1]
        )

