    float_precision = ".3f"
    match target:
        case "p1":
            p1 = float(
                format((values["p2"] * values["v2"]) / values["v1"], float_precision)
            )
            return {"p1": f"{p1} Pa"}
        case "v1":
            v1 = float(
                format((values["p2"] * values["v2"]) / values["p1"], float_precision)
            )
            return {"v1": f"{v1} L"}
        case "p2":
            p2 = float(
                format((values["p1"] * values["v1"]) / values["v2"], float_precision)
            )
            return {"p2": f"{p2} Pa"}
        case _:
            v2 = float(
