def mean_threshold(image: Image.Image) -> Image.Image:
    """image: is a grayscale PIL image object"""
    height, width = image.size
    mean = 0
    pixels = image.load()
    for i in range(width):
        for j in range(height):
            pixel = pixels[j, i]
            mean += pixel
    mean //= width * height

    for j in range(width):
        for i in range(height):
            pixels[i, j] = 255 if pixels[i, j] > mean else 0
    return image

def move_to_front_encode(text: str, alphabet: str) -> list[int]:
    """Encode text using the move-to-front transform."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    symbols = _validated_alphabet(alphabet)
    encoded_text: list[int] = []

    for char in text:
        try:
            char_index = symbols.index(char)
        except ValueError:
            message = f"character {char!r} is not in the alphabet"
            raise ValueError(message) from None
        encoded_text.append(char_index)
        symbols.insert(0, symbols.pop(char_index))

    return encoded_text

def partition(arr: list[int], low: int, high: int) -> int:
    """Partitions list based on the pivot element."""
    pivot = arr[high]
    i = low - 1
    for j in range(low, high):
        if arr[j] >= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]
    arr[i + 1], arr[high] = arr[high], arr[i + 1]
    return i + 1

def _fib(n: int) -> tuple[int, int]:
    if n == 0:  # (F(0), F(1))
        return (0, 1)

    # F(2n) = F(n)[2F(n+1) - F(n)]
    # F(2n+1) = F(n+1)^2+F(n)^2
    a, b = _fib(n // 2)
    c = a * (b * 2 - a)
    d = a * a + b * b
    return (d, c + d) if n % 2 else (c, d)

def charging_capacitor(
    source_voltage: float,  # voltage in volts.
    resistance: float,  # resistance in ohms.
    capacitance: float,  # capacitance in farads.
    time_sec: float,  # time in seconds after charging initiation of capacitor.
) -> float:
    """Find capacitor voltage at any nth second after initiating its charging."""

    if source_voltage <= 0:
        raise ValueError("Source voltage must be positive.")
    if resistance <= 0:
        raise ValueError("Resistance must be positive.")
    if capacitance <= 0:
        raise ValueError("Capacitance must be positive.")
    return round(source_voltage * (1 - exp(-time_sec / (resistance * capacitance))), 3)

