def search[T: Comparable](
    list_data: list[T], key: T, left: int = 0, right: int = 0
) -> int:
    """Iterate through the array to find the index of key using recursion."""
    right = right or len(list_data) - 1
    if left > right:
        return -1
    elif list_data[left] == key:
        return left
    elif list_data[right] == key:
        return right
    else:
        return search(list_data, key, left + 1, right - 1)

def comp_and_swap[T: Comparable](
    array: list[T], index1: int, index2: int, direction: int
) -> None:
    """Compare the value at given index1 and index2 of the array and swap them as per"""
    if (direction == 1 and array[index2] < array[index1]) or (
        direction == 0 and array[index1] < array[index2]
    ):
        array[index1], array[index2] = array[index2], array[index1]

def boyer_moore_horspool_search(text: str, pattern: str) -> int:
    """Return the index of the first occurrence of ``pattern`` in ``text``"""
    pattern_length = len(pattern)
    text_length = len(text)
    if pattern_length == 0:
        return 0
    if pattern_length > text_length:
        return -1

    shift_table = _build_shift_table(pattern)
    skip = 0
    while text_length - skip >= pattern_length:
        index = pattern_length - 1
        while index >= 0 and pattern[index] == text[skip + index]:
            index -= 1
        if index < 0:
            return skip
        skip += shift_table.get(text[skip + pattern_length - 1], pattern_length)
    return -1

def is_valid(
    puzzle: list[list[str]], word: str, row: int, col: int, vertical: bool
) -> bool:
    """Check if a word can be placed at the given position."""
    rows, cols = len(puzzle), len(puzzle[0])
    for i, ch in enumerate(word):
        r, c = (row + i, col) if vertical else (row, col + i)
        if r >= rows or c >= cols:
            return False
        cell = puzzle[r][c]
        if cell not in ("", ch):
            return False
    return True

def check(binary: list[str]) -> list[str]:
    pi = []
    while True:
        check1 = ["$"] * len(binary)
        temp = []
        for i in range(len(binary)):
            for j in range(i + 1, len(binary)):
                k = compare_string(binary[i], binary[j])
                if k is False:
                    check1[i] = "*"
                    check1[j] = "*"
                    temp.append("X")
        for i in range(len(binary)):
            if check1[i] == "$":
                pi.append(binary[i])
        if len(temp) == 0:
            return pi
        binary = list(set(temp))

def decode(coded: str) -> str:
    """Decodes from Baconian cipher"""
    if set(coded) - {"A", "B", " "} != set():
        raise Exception("decode() accepts only 'A', 'B' and spaces")
    decoded = ""
    for word in coded.split():
        while len(word) != 0:
            decoded += decode_dict[word[:5]]
            word = word[5:]
        decoded += " "
    return decoded.strip()

def binary_to_gray(binary_number: int) -> int:
    """Convert a binary number to its Gray Code equivalent."""
    if not isinstance(binary_number, int):
        raise TypeError("Input must be an integer")
    if binary_number < 0:
        raise ValueError("Input must be a non-negative integer")

    return binary_number ^ (binary_number >> 1)

def move_to_front_decode(encoded_text: list[int], alphabet: str) -> str:
    """Decode a move-to-front encoded list of indexes."""
    symbols = _validated_alphabet(alphabet)
    decoded_text = []

    for index in encoded_text:
        if not 0 <= index < len(symbols):
            message = f"index {index} is not valid for alphabet size {len(symbols)}"
            raise ValueError(message)
        decoded_text.append(symbols[index])
        symbols.insert(0, symbols.pop(index))

    return "".join(decoded_text)

def kth_largest_element(arr: list[int], position: int) -> int:
    """Finds the kth largest element in a list."""
    if not arr:
        return -1
    if not isinstance(position, int):
        raise ValueError("The position should be an integer")
    if not 1 <= position <= len(arr):
        raise ValueError("Invalid value of 'position'")
    low, high = 0, len(arr) - 1
    while low <= high:
        if low > len(arr) - 1 or high < 0:
            return -1
        pivot_index = partition(arr, low, high)
        if pivot_index == position - 1:
            return arr[pivot_index]
        elif pivot_index > position - 1:
            high = pivot_index - 1
        else:
            low = pivot_index + 1
    return -1

