    raise ValueError("One and only one argument must be 0")

def solution(n: int = 4000000) -> int:
    """Returns the sum of all even fibonacci sequence elements that are lower"""

    even_fibs = []
    a, b = 0, 1
    while b <= n:
        if b % 2 == 0:
            even_fibs.append(b)
        a, b = b, a + b
    return sum(even_fibs)

def binary_search_by_recursion(
    sorted_collection: list[int],
    item: int,
    left: int = 0,
    right: int | None = None,
) -> int:
    """Pure implementation of the binary search algorithm in Python using recursion"""
    if list(sorted_collection) != sorted(sorted_collection):
        raise ValueError("sorted_collection must be sorted in ascending order")
    if right is None:
        right = len(sorted_collection) - 1

    # Recursive core: ``left`` and ``right`` are always concrete indices here, so the
    # window can only shrink. Keeping the recursion flat (no ``None`` sentinel, no
    # re-expansion) is what prevents the runaway recursion when the item sits below
    # ``sorted_collection[0]`` and ``right`` legitimately drops below ``left``.
    def _search(left: int, right: int) -> int:
        if right < left:
            return -1

        midpoint = left + (right - left) // 2

        if sorted_collection[midpoint] == item:
            return midpoint
        elif sorted_collection[midpoint] > item:
            return _search(left, midpoint - 1)
        else:
            return _search(midpoint + 1, right)

    return _search(left, right)

def bitonic_sort[T: Comparable](
    array: list[T], low: int, length: int, direction: int
) -> None:
    """This function first produces a bitonic sequence by recursively sorting its two"""
    if length > 1:
        middle = int(length / 2)
        bitonic_sort(array, low, middle, 1)
        bitonic_sort(array, low + middle, middle, 0)
        bitonic_merge(array, low, length, direction)

def boyer_moore_horspool_search_all(text: str, pattern: str) -> list[int]:
    """Return every starting index where ``pattern`` occurs in ``text``."""
    pattern_length = len(pattern)
    text_length = len(text)
    if pattern_length == 0:
        return list(range(text_length + 1))
    if pattern_length > text_length:
        return []

    shift_table = _build_shift_table(pattern)
    matches: list[int] = []
    skip = 0
    while text_length - skip >= pattern_length:
        index = pattern_length - 1
        while index >= 0 and pattern[index] == text[skip + index]:
            index -= 1
        if index < 0:
            matches.append(skip)
            skip += 1
        else:
            skip += shift_table.get(text[skip + pattern_length - 1], pattern_length)
    return matches

