def _normalize_weights(weights: np.ndarray, num_clients: int) -> np.ndarray:
    if weights.shape != (num_clients,):
        msg = f"weights must have shape ({num_clients},)"
        raise ValueError(msg)
    if np.any(weights < 0):
        raise ValueError("weights must be non-negative")
    total = float(weights.sum())
    if total <= 0.0:
        raise ValueError("weights must sum to a positive value")
    return weights / total

def autocorrelation(data: list[float], lag: int) -> float:
    """Calculate the autocorrelation of a time series at a given lag."""
    if lag >= len(data):
        raise ValueError("Lag must be less than the length of the data.")

    n = len(data)
    mean = sum(data) / n
    variance = sum((x - mean) ** 2 for x in data) / n

    if variance == 0:
        raise ValueError("Variance of data is zero, autocorrelation undefined.")

    covariance = (
        sum((data[i] - mean) * (data[i - lag] - mean) for i in range(lag, n)) / n
    )

    return covariance / variance

def largest_square_area_in_matrix_top_down_approch_with_dp(
    rows: int, cols: int, mat: list[list[int]]
) -> int:
    """Function updates the largest_square_area[0], if recursive call found"""

    def update_area_of_max_square_using_dp_array(
        row: int, col: int, dp_array: list[list[int]]
    ) -> int:
        if row >= rows or col >= cols:
            return 0
        if dp_array[row][col] != -1:
            return dp_array[row][col]

        right = update_area_of_max_square_using_dp_array(row, col + 1, dp_array)
        diagonal = update_area_of_max_square_using_dp_array(row + 1, col + 1, dp_array)
        down = update_area_of_max_square_using_dp_array(row + 1, col, dp_array)

        if mat[row][col]:
            sub_problem_sol = 1 + min([right, diagonal, down])
            largest_square_area[0] = max(largest_square_area[0], sub_problem_sol)
            dp_array[row][col] = sub_problem_sol
            return sub_problem_sol
        else:
            return 0

    largest_square_area = [0]
    dp_array = [[-1] * cols for _ in range(rows)]
    update_area_of_max_square_using_dp_array(0, 0, dp_array)

    return largest_square_area[0]

def greedy(item, max_cost, key_func):
    items_copy = sorted(item, key=key_func, reverse=True)
    result = []
    total_value, total_cost = 0.0, 0.0
    for i in range(len(items_copy)):
        if (total_cost + items_copy[i].get_weight()) <= max_cost:
            result.append(items_copy[i])
            total_cost += items_copy[i].get_weight()
            total_value += items_copy[i].get_value()
    return (result, total_value)

def doppler_effect(
    org_freq: float, wave_vel: float, obs_vel: float, src_vel: float
) -> float:
    """Input Parameters:"""

    if wave_vel == src_vel:
        raise ZeroDivisionError(
            "Division by zero implies vs=v and observer in front of the source"
        )
    doppler_freq = (org_freq * (wave_vel + obs_vel)) / (wave_vel - src_vel)
    if doppler_freq <= 0:
        raise ValueError(
            "Non-positive frequency implies vs>v or v0>v (in the opposite direction)"
        )
    return doppler_freq

def solution(n: int = 4000000) -> int:
    """Returns the sum of all even fibonacci sequence elements that are lower"""

    fib = [0, 1]
    i = 0
    while fib[i] <= n:
        fib.append(fib[i] + fib[i + 1])
        if fib[i + 2] > n:
            break
        i += 1
    total = 0
    for j in range(len(fib) - 1):
        if fib[j] % 2 == 0:
            total += fib[j]

    return total

@lru_cache
def fibonacci(k: int) -> int:
    """Finds fibonacci number in index k."""
    if not isinstance(k, int):
        raise TypeError("k must be an integer.")
    if k < 0:
        raise ValueError("k integer must be greater or equal to zero.")
    match k:
        case 0:
            return 0
        case 1:
            return 1
        case _:
            return fibonacci(k - 1) + fibonacci(k - 2)

def bubble_sort_iterative[T: Comparable](collection: list[T]) -> list[T]:
    """Pure implementation of the bubble sort algorithm in Python (iterative)."""
    length = len(collection)
    for i in reversed(range(length)):
        swapped = False
        for j in range(i):
            if collection[j + 1] < collection[j]:
                swapped = True
                collection[j], collection[j + 1] = collection[j + 1], collection[j]
        if not swapped:
            break  # Stop iteration if the collection is sorted.
    return collection

def camel_to_snake_case(input_str: str) -> str:
    """Transforms a camelCase (or PascalCase) string to snake_case"""

    # check for invalid input type
    if not isinstance(input_str, str):
        msg = f"Expected string as input, found {type(input_str)}"
        raise ValueError(msg)

    snake_str = ""

    for index, char in enumerate(input_str):
        if char.isupper():
            snake_str += "_" + char.lower()

        # if char is lowercase but proceeded by a digit:
        elif input_str[index - 1].isdigit() and char.islower():
            snake_str += "_" + char

        # if char is a digit proceeded by a letter:
        elif input_str[index - 1].isalpha() and char.isnumeric():
            snake_str += "_" + char.lower()

        # if char is not alphanumeric:
        elif not char.isalnum():
            snake_str += "_"

        else:
            snake_str += char

    # remove leading underscore
    if snake_str[0] == "_":
        snake_str = snake_str[1:]

    return snake_str

def generate_parentheses_iterative(length: int) -> list[str]:
    """Generate all valid combinations of parentheses (Iterative Approach)."""
    if length == 0:
        return [""]

    result: list[str] = []
    stack: list[tuple[str, int, int]] = []

    # Each element in stack is a tuple (current_combination, open_count, close_count)
    stack.append(("", 0, 0))

    while stack:
        current_combination, open_count, close_count = stack.pop()

        if len(current_combination) == 2 * length:
            result.append(current_combination)
            continue

        if open_count < length:
            stack.append((current_combination + "(", open_count + 1, close_count))

        if close_count < open_count:
            stack.append((current_combination + ")", open_count, close_count + 1))

    return result

def fwht_xor(sequence: list[int], inverse: bool = False) -> list[int]:
    """Perform Fast Walsh-Hadamard Transform (or inverse) for XOR operation."""
    sequence_length = len(sequence)
    if sequence_length == 0 or (sequence_length & (sequence_length - 1)) != 0:
        raise ValueError("Length of sequence must be a positive power of 2.")

    result = list(sequence)
    half_block = 1
    while half_block < sequence_length:
        block_size = half_block * 2
        for block_start in range(0, sequence_length, block_size):
            for offset in range(half_block):
                left_index = block_start + offset
                right_index = left_index + half_block
                left_val = result[left_index]
                right_val = result[right_index]
                result[left_index] = left_val + right_val
                result[right_index] = left_val - right_val
        half_block *= 2

    if inverse:
        if any(element % sequence_length != 0 for element in result):
            raise ValueError(
                "Inverse XOR transform requires elements divisible by sequence length."
            )
        result = [element // sequence_length for element in result]
    return result

def generate_key(message: str, key: str) -> str:
    x = len(message)
    i = 0
    while True:
        if x == i:
            i = 0
        if len(key) == len(message):
            break
        key += key[i]
        i += 1
    return key

def bin_to_octal(bin_string: str) -> str:
    if not all(char in "01" for char in bin_string):
        raise ValueError("Non-binary value was passed to the function")
    if not bin_string:
        raise ValueError("Empty string was passed to the function")
    oct_string = ""
    while len(bin_string) % 3 != 0:
        bin_string = "0" + bin_string
    bin_string_in_3_list = [
        bin_string[index : index + 3]
        for index in range(len(bin_string))
        if index % 3 == 0
    ]
    for bin_group in bin_string_in_3_list:
        oct_val = 0
        for index, val in enumerate(bin_group):
            oct_val += int(2 ** (2 - index) * int(val))
        oct_string += str(oct_val)
    return oct_string

def merge_sorted_arrays(nums1: list[int], nums2: list[int]) -> list[int]:
    """Merge two sorted arrays into one sorted array."""
    for nums in (nums1, nums2):
        if list(nums) != sorted(nums):
            msg = f"{nums = } is not sorted"
            raise ValueError(msg)
    # If one array is empty, simply return the other.
    if not nums1:
        return nums2
    if not nums2:
        return nums1

    # Two-pointer approach to merge both sorted arrays.
    i, j = 0, 0
    merged = []

    while i < len(nums1) and j < len(nums2):
        if nums1[i] <= nums2[j]:
            merged.append(nums1[i])
            i += 1
        else:
            merged.append(nums2[j])
            j += 1

    # Append remaining elements if any.
    merged.extend(nums1[i:])
    merged.extend(nums2[j:])

    return merged

def my_laplacian(src: np.ndarray, ksize: int) -> np.ndarray:
    """:param src: the source image, which should be a grayscale or color image."""
    kernels = {
        1: np.array([[0, -1, 0], [-1, 4, -1], [0, -1, 0]]),
        3: np.array([[0, 1, 0], [1, -4, 1], [0, 1, 0]]),
        5: np.array(
            [
                [0, 0, -1, 0, 0],
                [0, -1, -2, -1, 0],
                [-1, -2, 16, -2, -1],
                [0, -1, -2, -1, 0],
                [0, 0, -1, 0, 0],
            ]
        ),
        7: np.array(
            [
                [0, 0, 0, -1, 0, 0, 0],
                [0, 0, -2, -3, -2, 0, 0],
                [0, -2, -7, -10, -7, -2, 0],
                [-1, -3, -10, 68, -10, -3, -1],
                [0, -2, -7, -10, -7, -2, 0],
                [0, 0, -2, -3, -2, 0, 0],
                [0, 0, 0, -1, 0, 0, 0],
            ]
        ),
    }
    if ksize not in kernels:
        msg = f"ksize must be in {tuple(kernels)}"
        raise ValueError(msg)

    # Apply the Laplacian kernel using convolution
    return filter2D(
        src, CV_64F, kernels[ksize], 0, borderType=BORDER_DEFAULT, anchor=(0, 0)
    )

def max_cross_sum(
    arr: Sequence[float], low: int, mid: int, high: int
) -> tuple[int, int, float]:
    left_sum, max_left = float("-inf"), -1
    right_sum, max_right = float("-inf"), -1

    summ: int | float = 0
    for i in range(mid, low - 1, -1):
        summ += arr[i]
        if summ > left_sum:
            left_sum = summ
            max_left = i

    summ = 0
    for i in range(mid + 1, high + 1):
        summ += arr[i]
        if summ > right_sum:
            right_sum = summ
            max_right = i

    return max_left, max_right, (left_sum + right_sum)

