def electric_power(voltage: float, current: float, power: float) -> tuple:
    """This function can calculate any one of the three (voltage, current, power),"""
    if (voltage, current, power).count(0) != 1:
        raise ValueError("Exactly one argument must be 0")
    if power < 0:
        raise ValueError(
            "Power cannot be negative in any electrical/electronics system"
        )
    if voltage == 0:
        return Result("voltage", power / current)
    elif current == 0:
        return Result("current", power / voltage)
    elif power == 0:
        return Result("power", float(round(abs(voltage * current), 2)))
    else:
        raise AssertionError

def kelly_criterion_extended(
    win_probability: float, win_amount: float, loss_amount: float
) -> float:
    """Calculate the Kelly fraction using explicit win and loss amounts."""
    if win_probability <= 0 or win_probability >= 1:
        raise ValueError("win_probability must be between 0 and 1 (exclusive)")
    if win_amount <= 0:
        raise ValueError("win_amount must be > 0")
    if loss_amount <= 0:
        raise ValueError("loss_amount must be > 0")

    loss_probability = 1 - win_probability
    # Convert to win/loss ratio format: b = win_amount / loss_amount
    # Then apply Kelly formula: (p * b - q) / b
    win_loss_ratio = win_amount / loss_amount
    kelly_fraction = (win_probability * win_loss_ratio - loss_probability) / (
        win_loss_ratio
    )

    return kelly_fraction

def expand_search(
    graph: dict[int, list[int]],
    queue: deque[int],
    parents: dict[int, int | None],
    opposite_direction_parents: dict[int, int | None],
) -> int | None:
    if not queue:
        return None

    current = queue.popleft()
    for neighbor in graph[current]:
        if neighbor in parents:
            continue

        parents[neighbor] = current
        queue.append(neighbor)

        # Check if this creates an intersection
        if neighbor in opposite_direction_parents:
            return neighbor

    return None

@dataclass
class TreeNode:
    """A node in a Frequent Pattern tree."""

    name: str
    count: int
    parent: TreeNode | None = None
    children: dict[str, TreeNode] = field(default_factory=dict)
    node_link: TreeNode | None = None

    def __repr__(self) -> str:
        return f"TreeNode({self.name!r}, {self.count!r}, {self.parent!r})"

    def inc(self, num_occur: int) -> None:
        self.count += num_occur

    def disp(self, ind: int = 1) -> None:
        print(f"{'  ' * ind} {self.name}  {self.count}")
        for child in self.children.values():
            child.disp(ind + 1)

